package com.huan.capture.sr.webrtc.transfer;import androidx.annotation.CallSuper;import com.huan.capture.sr.webrtc.L;import org.webrtc.IceCandidate;import org.webrtc.SessionDescription;/** * <br> * * <br> */public class TransferAdapter {    private AnswerCallback mAnswerCallback;    @CallSuper    public void onIceCandidate(IceCandidate iceCandidate) {        L.logD("onIceCandidate");    }    public void sendOfferSdp(SessionDescription sdp) {        L.logD("LOCAL SDP:" + sdp.description);    }    public void setAnswerCallback(AnswerCallback callback) {        mAnswerCallback = sdp -> {            L.logD("REMOTE SDP:" + sdp.description);            callback.onAnswerSdp(sdp);        };    }    public AnswerCallback getAnswerCallback() {        return mAnswerCallback;    }    public interface AnswerCallback {        void onAnswerSdp(SessionDescription sdp);    }}